import{z as f,x as p,o as t,c,q as d,j as i,D as a,d as o,s as l,S as n,b as s}from"./chunks/framework.C8m1ZpeB.js";const B=JSON.parse('{"title":"sk_buff","description":"","frontmatter":{"title":"sk_buff","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/skbuff.md","filePath":"cs/skbuff.md","lastUpdated":1791413859000}'),u={name:"cs/skbuff.md"};function b(E,e,k,A,m,_){const r=p("Mermaid");return t(),c("div",null,[e[2]||(e[2]=d('<h1 id="sk-buff" tabindex="-1">sk_buff <a class="header-anchor" href="#sk-buff" aria-label="Permalink to &quot;sk_buff&quot;">​</a></h1><div class="epigraph"><p>sk_buff 是内核里一包数据的控制块：头尾指针、分片、校验卸载标志、以及指向套接字与设备的钩子。</p><footer>—— 据 Linux networking 文档对 sk_buff 的说明；Stevens 对 mbuf 的对照；Benvenuti, <em>Understanding Linux Network Internals</em></footer></div><p><a href="/cs/discard-trim">上一课</a>收口存储。包不是 bio：可变头、要推拉协议层、可能非线性。<a href="/cs/sendfile-splice">sendfile</a> 已经把页挂出去。缺口是 <strong>sk_buff</strong>：网络栈的统一对象，后课收发路径都围着它转。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>以太网帧、IP、TCP 头长度不同，还要预留推空间。若每层拷贝，带宽被 CPU 吃掉。sk_buff：线性区 + paged frags（页数组），<code>skb_push</code>/<code>skb_pull</code> 只动指针。缺口：克隆（<code>skb_clone</code> 共享数据、写时拷贝）服务组播与排队；<code>headroom</code> 给驱动 DMA 对齐；与 <a href="/cs/page-cache">页缓存</a> 的关系——sendfile 的页成为 frag，不经过用户。本课不把 eBPF 改包提前写完。</p><p><span class="marginnote">mbuf 是 BSD 亲戚。不要把 skb 当成数据库行：它是包描述符，生命期从驱动到套接字或相反。</span></p><p><span class="marginnote">术语翻译：<code>skb_push</code>/<code>skb_pull</code> 就是「推头/剥头」——发送时 TCP 头往线性区前面压一截（<code>push</code>），接收时收包方把以太网头往前拉掉一截（<code>pull</code>）。动的只是 <code>data</code> 指针，字节一个都不搬。</span></p><p><span class="marginnote">直觉类比：把 skb 想成快递面单——面单本身（控制块）写着重量、目的地、状态标志，货物（数据缓冲）可以整箱、也可以拆成几个袋子（paged frags）。克隆是把面单复印一份、两份单子指同一批货。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>接收：驱动 DMA 进页，建 skb，把协议指针指向以太网头。发送：套接字分配 skb，协议压头，qdisc 排队，驱动从 frags 做 scatter-gather。释放：引用计数到零还页。对照 bio：bio 是块范围；skb 是字节流上的一段报文，可分片、可 GSO。</p>',10)),(t(),i(n,null,{default:a(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIN%5B%22%E7%BA%BF%E6%80%A7%20head%22%5D%20--%3E%20META%5B%22sk_buff%20%E5%85%83%E6%95%B0%E6%8D%AE%22%5D%0A%20%20FR%5B%22paged%20frags%22%5D%20--%3E%20META%0A%20%20META%20--%3E%20SOCK%5B%22sk%22%5D%0A%20%20META%20--%3E%20DEV%5B%22net_device%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[o(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=s("h2",{id:"机制",tabindex:"-1"},[o("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=s("p",null,"skb 让各协议层共享同一缓冲而不拷贝，是零拷贝网络的内核侧原语。元数据（hash、checksum status、tstamp）决定后课 GRO/GSO 能否卸载。不要写成量化行情包格式。与 cgroup：skb 可打 classid，但会计在后课。",-1)),e[5]||(e[5]=s("p",null,"一包数据下行（发送）时头是怎么长出来的？各层只压头、不拷贝：",-1)),(t(),i(n,null,{default:a(()=>[l(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%BA%94%E7%94%A8%E5%86%99%E5%A5%97%E6%8E%A5%E5%AD%97%22%5D%20--%3E%20B%5B%22TCP%20%E5%88%86%E9%85%8D%20skb%3Cbr%3E%E5%8E%8B%20TCP%20%E5%A4%B4%EF%BC%9Askb_push%22%5D%0A%20%20B%20--%3E%20C%5B%22IP%20%E5%8E%8B%20IP%20%E5%A4%B4%22%5D%0A%20%20C%20--%3E%20D%5B%22qdisc%20%E6%8E%92%E9%98%9F%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%BB%A5%E5%A4%AA%E7%BD%91%E5%8E%8B%E5%B8%A7%E5%A4%B4%22%5D%0A%20%20E%20--%3E%20F%5B%22%E9%A9%B1%E5%8A%A8%20scatter-gather%3Cbr%3E%E6%8A%8A%20frags%20%E4%BA%A4%E7%BB%99%20DMA%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[o(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=d('<p>这一步如果做错了，代价是整条带宽：任何一层若改用 <code>memcpy</code> 重排数据而不是压头，千兆链路上 CPU 就会先于网卡跑满。<code>headroom</code> 预留不足同理——中途发现没地方压头，就只能搬数据补洞。</p><p>错误路径：drop 统计在此对象上加，tcpdump 抓的也是它的镜像。</p><p>实现上：clone 只拷控制块，写头时才 pskb_expand_head。GSO 包的 gso_size 让协议层把一包当多段。释放路径必须处理分片页的引用，否则页缓存钉死。 读法上只引用<a href="/cs/discard-trim">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>sk_buff</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 skb 扩展（secpath、nfct）的全部指针。不保证用户态包 I/O 用同一结构——DPDK 用 mbuf 自己的。下一课驱动如何把中断收成 napi 轮询：NAPI。</p><p>版本字段会变，课序钉的是机制对象「sk_buff」，不是某一主线内核的结构体名。 后课默认：包在内核里是 sk_buff。网卡中断与轮询如何灌 skb，下一课 NAPI。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>sk_buff 用指针与分片描述一包，可克隆共享数据。</li><li>发送接收路径都围绕它，而不是 bio。</li><li>NAPI 是下一课。</li><li>出处：Linux skb；Benvenuti <em>ULNI</em>；Stevens mbuf。</li></ul>',10))])}const D=f(u,[["render",b]]);export{B as __pageData,D as default};
